import { isDueMonth } from "../dueDate";
import type { Priority, ProjectFields } from "../remote/api";

/** What the Client app sees of a Project file. Everything else stays in the vault. */
export interface SharedProject {
	path: string;
	/** App id (`suivi_id:` frontmatter), generated by the plugin and written before the first Push sends it. */
	suiviId?: string;
	fields: ProjectFields;
}

export type ReadResult =
	| { ok: true; project: SharedProject }
	| { ok: false; path: string; suiviId?: string; error: string };

/** The YAML spellings of null, read by `readFrontmatter` as plain strings. */
const YAML_NULL = new Set(["null", "Null", "NULL", "~"]);

/** Priority pushed for an open Project without a valid `priority:`. */
const DEFAULT_PRIORITY = 5;

/**
 * Reads the shared fields of a Project note: title (file name), the
 * `# Description` section, `priority:` (`0`–`5` or `pr`), `archived:` (Done,
 * then no Priority) and `due_date:` frontmatter; `status:` means nothing here.
 * Returns null for `prive: true` Projects, which never leave the vault. A
 * due_date that isn't a month (`YYYY-MM`) is an error naming the note.
 */
export function readSharedProject(path: string, content: string): ReadResult | null {
	const lines = content.split("\n");
	const fm = readFrontmatter(lines);
	if (fm.prive === "true") return null;

	const refuse = (error: string): ReadResult => ({ ok: false, path, ...(fm.suivi_id ? { suiviId: fm.suivi_id } : {}), error });
	const done = fm.archived === "true";
	const dueDate = !fm.due_date || YAML_NULL.has(fm.due_date) ? null : fm.due_date;
	if (dueDate !== null && !isDueMonth(dueDate)) return refuse(`Invalid due_date "${dueDate}" in ${path}`);

	const priority = done ? null : readPriority(fm.priority);

	return {
		ok: true,
		project: {
			path,
			suiviId: fm.suivi_id || undefined,
			fields: {
				title: basename(path),
				description: descriptionSection(lines, fm.end),
				priority,
				done,
				due_date: dueDate,
			},
		},
	};
}

/** A `priority:` value: `pr` (any case), or a number capped at 5; anything else is P5. */
function readPriority(value: string | undefined): Priority {
	if (value?.toLowerCase() === "pr") return "pr";
	return /^\d+$/.test(value ?? "") ? (Math.min(Number(value), 5) as Priority) : DEFAULT_PRIORITY;
}

/** Raw `key: value` strings of the frontmatter (quotes stripped, no type coercion). */
export function readFrontmatter(lines: string[]): Record<string, string> & { end: number } {
	const out: Record<string, string> = {};
	if (lines[0]?.trim() !== "---") return Object.assign(out, { end: 0 });
	let i = 1;
	for (; i < lines.length; i++) {
		const line = lines[i]!;
		if (line.trim() === "---") break;
		const m = line.match(/^(\w+)\s*:\s*(.*)$/);
		if (m) out[m[1]!] = m[2]!.trim().replace(/^(["'])(.*)\1$/, "$2");
	}
	return Object.assign(out, { end: i + 1 });
}

/** Body of the `# Description` heading (levels 1–3), up to the next heading of the same or higher level. */
function descriptionSection(lines: string[], from: number): string {
	let start = -1;
	let level = 0;
	for (let i = from; i < lines.length; i++) {
		const m = lines[i]!.match(/^(#{1,6})\s+(.+?)\s*$/);
		if (!m) continue;
		if (start < 0) {
			if (m[1]!.length <= 3 && m[2]!.toLowerCase() === "description") {
				start = i + 1;
				level = m[1]!.length;
			}
		} else if (m[1]!.length <= level) {
			return trimSection(lines.slice(start, i));
		}
	}
	return start < 0 ? "" : trimSection(lines.slice(start));
}

function trimSection(lines: string[]): string {
	// The vault's template puts a `---` rule under each heading.
	const body = lines[0]?.trim() === "---" ? lines.slice(1) : lines;
	return body.join("\n").trim();
}

function basename(path: string): string {
	const file = path.slice(path.lastIndexOf("/") + 1);
	return file.endsWith(".md") ? file.slice(0, -3) : file;
}
